17	// MCPService serves the OpenAPI-driven MCP endpoint.
18	type MCPService struct {
19		profile *profile.Profile
20	
21		operationsByTool map[string]*registeredOperation
22		handler          http.Handler
23	}
24	
25	// NewMCPService creates an MCP service backed by the in-process API routes.
26	func NewMCPService(profile *profile.Profile, echoServer *echo.Echo) (*MCPService, error) {
27		spec, err := loadMCPServiceOpenAPISpec()
28		if err != nil {
29			return nil, err
30		}
31		registry, err := buildOperationRegistry(spec)
32		if err != nil {
33			return nil, err
34		}
35		tools, operationsByTool, err := buildCuratedTools(registry)
36		if err != nil {
37			return nil, err
38		}
39	
40		version := "dev"
41		if profile != nil && profile.Version != "" {
42			version = profile.Version
43		}
44		server := sdkmcp.NewServer(&sdkmcp.Implementation{
45			Name:    "memos",
46			Version: version,
47		}, nil)
48	
49		adapter := newAPIAdapter(echoServer)
50		for _, tool := range tools {
51			operation := operationsByTool[tool.Name]
52			server.AddTool(tool, newMCPToolHandler(adapter, operation))
53		}
54	
55		handler := sdkmcp.NewStreamableHTTPHandler(func(*http.Request) *sdkmcp.Server {
56			return server
57		}, &sdkmcp.StreamableHTTPOptions{
58			Stateless:    true,
59			JSONResponse: true,
60			// memos is typically served behind a reverse proxy with the app bound to a
61			// loopback address while the public Host header is a real domain. The SDK's
62			// DNS-rebinding guard treats that shape as an attack and rejects every
63			// request with 403 ("invalid Host header"). Disable it and rely on memos'
64			// own Origin/Host allowlist (see RegisterRoutes -> isAllowedMCPOrigin) for
65			// CSRF / DNS-rebinding protection instead.
66			DisableLocalhostProtection: true,
67		})
68	
69		return &MCPService{
70			profile:          profile,
71			operationsByTool: operationsByTool,
72			handler:          handler,
73		}, nil
74	}
75	
76	func loadMCPServiceOpenAPISpec() (*openAPISpec, error) {
77		spec := &openAPISpec{}
78		if err := yaml.Unmarshal(memosproto.OpenAPIYAML(), spec); err != nil {
79			return nil, errors.Wrap(err, "failed to parse embedded OpenAPI spec")
80		}
81		if spec.Paths == nil {
82			return nil, errors.New("embedded OpenAPI spec has no paths")
83		}
84		return spec, nil
85	}
86	
87	func newMCPToolHandler(adapter *apiAdapter, operation *registeredOperation) sdkmcp.ToolHandler {
88		return func(ctx context.Context, request *sdkmcp.CallToolRequest) (*sdkmcp.CallToolResult, error) {
89			arguments := map[string]any{}
90			if request.Params != nil && len(request.Params.Arguments) > 0 {
91				if err := json.Unmarshal(request.Params.Arguments, &arguments); err != nil {
92					return newToolErrorResult(errors.Wrap(err, "failed to decode MCP tool arguments").Error()), nil
93				}
94			}
95			if err := validateToolArguments(operation.InputSchema, arguments); err != nil {
96				return newToolErrorResult(err.Error()), nil
97			}
98	
99			authorization := ""
100			if request.Extra != nil {
101				authorization = request.Extra.Header.Get("Authorization")
102			}
103			return adapter.execute(ctx, operation.Operation, arguments, authorization)
104		}
105	}
106	
107	// RegisterRoutes registers the streamable HTTP MCP endpoint.
108	func (s *MCPService) RegisterRoutes(echoServer *echo.Echo) {
109		echoServer.Any("/mcp", func(c *echo.Context) error {
110			request := c.Request()
111			if !isAllowedMCPOrigin(request.Host, request.Header.Get("Origin"), s.profile) {
112				return c.NoContent(http.StatusForbidden)
113			}
114			s.handler.ServeHTTP(c.Response(), request)
115			return nil
116		})
117	}
